// Study notes: docs/learning/notes/test/inventory/InventoryControllerTest.kt.md
package com.robertwoolbright.inventory.inventory

import com.robertwoolbright.inventory.support.TestcontainersConfiguration
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.context.SpringBootTest
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc
import org.springframework.context.annotation.Import
import org.springframework.http.MediaType
import org.springframework.jdbc.core.simple.JdbcClient
import org.springframework.test.json.JsonCompareMode
import org.springframework.test.web.servlet.MockMvc
import org.springframework.test.web.servlet.get

/**
 * `GET /inventory` through the full stack (MockMvc → controller → service → repository → Postgres),
 * checking status, content type and the exact JSON body against the contract.
 */
@SpringBootTest
@AutoConfigureMockMvc
@Import(TestcontainersConfiguration::class)
class InventoryControllerTest @Autowired constructor(
    private val mockMvc: MockMvc,
    private val jdbcClient: JdbcClient,
) {

    /** Starts every test from an empty table, since all tests in this context share one database. */
    @BeforeEach
    fun clearInventory() {
        jdbcClient.sql("DELETE FROM inventory").update()
    }

    private fun insert(skuId: String, quantity: Int) {
        jdbcClient.sql("INSERT INTO inventory (sku_id, quantity) VALUES (?, ?)")
            .params(skuId, quantity)
            .update()
    }

    /** Contract: "If no SKUs exist, returns an empty array." */
    @Test
    fun `GET inventory returns an empty JSON array when there are no SKUs`() {
        mockMvc.get("/inventory").andExpect {
            status { isOk() }
            content {
                contentType(MediaType.APPLICATION_JSON)
                json("[]", JsonCompareMode.STRICT)
            }
        }
    }

    /** Contract: a JSON array of InventoryItem (`skuId`, `quantity`), here in SKU id order. */
    @Test
    fun `GET inventory returns every SKU with its quantity`() {
        insert("widget", 5)
        insert("CW-XYCS-BM-01", 10)
        insert("sold-out", 0)

        mockMvc.get("/inventory").andExpect {
            status { isOk() }
            content {
                contentType(MediaType.APPLICATION_JSON)
                json(
                    """
                    [
                      {"skuId": "CW-XYCS-BM-01", "quantity": 10},
                      {"skuId": "sold-out", "quantity": 0},
                      {"skuId": "widget", "quantity": 5}
                    ]
                    """,
                    JsonCompareMode.STRICT,
                )
            }
        }
    }
}
// Study notes: docs/learning/notes/main/inventory/InventoryService.kt.md

package com.robertwoolbright.inventory.inventory


import org.springframework.stereotype.Service

/** Service class for the get /inventory flow. Use by controller layer and consumes the repository layer. */
@Service
class InventoryService(
    private val inventoryRepository: InventoryRepository
    ){
    
    /** Function that returns the list of sorted inventory items. */
    fun listInventory() : List<InventoryItem> = inventoryRepository.findAll()
    
}openapi: 3.0.3
info:
  title: Inventory API
  version: 1.0.0
paths:
  /inventory/{skuId}:
    parameters:
      - name: skuId
        in: path
        required: true
        schema:
          type: string
          example: CW-XYCS-BM-01
    get:
      summary: Get inventory for a SKU
      description: Returns the current quantity on hand for the specified SKU. Returns 404 if the SKU does not exist.
      operationId: getInventory
      responses:
        '200':
          description: Current inventory state for the sku
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/InventoryItem'
        '404':
          description: SKU not found
          content:
            text/plain:
              schema:
                $ref: '#/components/schemas/Error'
    post:
      summary: Create or update inventory for a SKU
      description: >
        Adds stock for the specified SKU. If the SKU does not yet exist in inventory,
        it is created with the given quantity. If it already exists, the quantity is
        added to the current stock. Returns the updated inventory state for the SKU.
      operationId: createInventory
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/InventoryQuantity'
      responses:
        '200':
          description: Current state of the item after update
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/InventoryItem'
        '400':
          description: Invalid request
          content:
            text/plain:
              schema:
                $ref: '#/components/schemas/Error'
  /inventory/{skuId}/purchase:
    parameters:
      - name: skuId
        in: path

